describe('Loading States for Assistive Technology', () => {
  beforeEach(() => {
    cy.visit('/data-table');
  });

  it('should communicate loading state to assistive users via aria-live region', () => {
    // Intercept the API call that triggers loading
    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: {
        data: [{ id: 1, name: 'Item 1' }, { id: 2, name: 'Item 2' }]
      }
    }).as('loadData');

    // Click the button to load data
    cy.get('[data-testid="load-data-button"]').click();

    // Verify loading indicator is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify aria-live region is present and has appropriate role
    cy.get('[data-testid="loading-status-aria-live"]').should('be.visible');
    cy.get('[data-testid="loading-status-aria-live"]').should('have.attr', 'aria-live', 'polite');

    // Verify loading message is announced
    cy.get('[data-testid="loading-status-aria-live"]').should('contain', 'Loading data');

    // Wait for API response
    cy.wait('@loadData');

    // Verify loading indicator is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify data is displayed
    cy.get('[data-testid="data-table"]').should('be.visible');
    cy.get('[data-testid="data-row"]').should('have.length', 2);

    // Verify aria-live region is cleared or updated
    cy.get('[data-testid="loading-status-aria-live"]').should('contain', 'Data loaded successfully');
  });

  it('should handle loading errors and communicate them to assistive users', () => {
    // Intercept the API call and simulate an error
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('loadDataError');

    // Click the button to load data
    cy.get('[data-testid="load-data-button"]').click();

    // Verify loading indicator is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Wait for API error response
    cy.wait('@loadDataError');

    // Verify loading indicator is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify error message is displayed in aria-live region
    cy.get('[data-testid="loading-status-aria-live"]').should('be.visible');
    cy.get('[data-testid="loading-status-aria-live"]').should('have.attr', 'aria-live', 'assertive');

    // Verify error message is announced
    cy.get('[data-testid="loading-status-aria-live"]').should('contain', 'Error loading data');
    cy.get('[data-testid="loading-status-aria-live"]').should('contain', 'Please try again');

    // Verify error state is visible
    cy.get('[data-testid="error-message"]').should('be.visible');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Verify data table is not displayed
    cy.get('[data-testid="data-table"]').should('not.exist');
  });
});
